import { useState } from "react";
import LeaveService from "../Services/LeaveService";
import { useNavigate } from "react-router-dom";

const Leave = () => {

    const navigate = useNavigate();

    const [leave, setLeave] = useState({
        leaveType: "",
        startDate: "",
        endDate: "",
        reason: "",
        status: "PENDING",
        employee: { id: "" }
    });

    const change = e => {
        const { name, value } = e.target;
        if (name === "id") setLeave({ ...leave, employee: { id: value } });
        else setLeave({ ...leave, [name]: value });
    };

    const save = e => {
        e.preventDefault();

        if (leave.end_date < leave.start_date) {
            alert("End date cannot be before start date");
            return;
        }

        LeaveService.createLeave(leave).then(() => {
            navigate("/dashboard", { state: { success: true } });
        });
    };

    return (
        <div style={{ padding: '48px 36px', background: '#e9ecef', minHeight: '100vh' }}>
            <div style={{ marginBottom: '28px' }}>
                <h3 style={{ fontWeight: '700', margin: 0 }}>Apply Leave</h3>
                <hr />
            </div>

            <div style={{ display: 'flex', gap: '32px' }}>

                <div style={{ background: '#fff', borderRadius: '10px', padding: '36px', maxWidth: '560px', boxShadow: '0 2px 16px rgba(0,0,0,0.08)' }}>

                    <form onSubmit={save}>

                        <div style={{ marginBottom: '20px' }}>
                            <input type="text" name="id" className="form-control" placeholder="Employee ID" value={leave.employee.id} onChange={change} required />
                        </div>

                        <select name="leaveType" className="form-control" value={leave.leaveType} onChange={change} style={{ marginBottom: '20px' }} required>
                            <option value="">Select Leave Type</option><option value="sick leave">Sick Leave</option><option value="holiday leave">Holiday Leave</option><option value="earned leave">Earned Leave</option>
                        </select>

                        <div style={{ marginBottom: '20px' }}>
                            <input type="date" name="startDate" className="form-control" value={leave.startDate} onChange={change} required />
                        </div>

                        <div style={{ marginBottom: '20px' }}>
                            <input type="date" name="endDate" className="form-control" value={leave.endDate} onChange={change} required />
                        </div>

                        <div style={{ marginBottom: '28px' }}>
                            <input type="text" name="reason" className="form-control" placeholder="Reason" value={leave.reason} onChange={change} />
                        </div>

                        <div style={{ display: 'flex', gap: '12px' }}>
                            <button type="submit" style={{ flex: 1, background: '#212529', color: '#fff', border: 'none', padding: '13px', borderRadius: '6px' }}>Apply</button>
                            <button type="button" onClick={() => navigate("/")} style={{ flex: 1, background: '#fff', border: '1px solid #ced4da', padding: '13px', borderRadius: '6px' }}>Back</button>
                        </div>

                    </form>
                </div>
            </div>
        </div>
    );
};

export default Leave;
